using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.NTF.Notificaciones;using GraphApi.Services.NTF.Notificaciones;namespace GraphApi.Controllers.NTF.Notificaciones{    /// <summary>    /// Gestión de Notificaciones: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("NTF/Legacy/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre Notificaciones")]    public class NotificacionesController : Controller    {        private readonly INotificacionesService _objService;        public NotificacionesController(INotificacionesService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los Notificaciones, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="notificacionID">NotificacionID</param>        /// <param name="usuarioID">UsuarioID</param>        /// <param name="titulo">Titulo</param>        /// <param name="mensaje">Mensaje</param>        /// <param name="leido">Leido</param>        /// <param name="fechaCreacionNotificacion">FechaCreacionNotificacion</param>        /// <param name="tipoNotificacionID">TipoNotificacionID</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de Notificaciones</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar Notificaciones",            Description = "Devuelve Notificaciones aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadNotificaciones>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadNotificaciones>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? notificacionID,            [FromQuery] int? usuarioID,            [FromQuery] string? titulo,            [FromQuery] string? mensaje,            [FromQuery] bool? leido,            [FromQuery] DateTime? fechaCreacionNotificacion,            [FromQuery] int? tipoNotificacionID,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetNotificacionesDynamic(                notificacionID,                 usuarioID,                 titulo,                 mensaje,                 leido,                 fechaCreacionNotificacion,                 tipoNotificacionID,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo Notificacione.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del Notificacione a crear.</param>        /// <returns>El Notificacione recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear Notificaciones",            Description = "Inserta un nuevo Notificacione en la base de datos."        )]        [ProducesResponseType(typeof(clReadNotificaciones), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadNotificaciones>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateNotificaciones objInput)        {            var vCreated = await _objService.CreateNotificaciones(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de Notificacione.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del Notificacione.</param>        /// <returns>El Notificacione actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar Notificaciones",            Description = "Actualiza uno o varios campos de Notificacione existente."        )]        [ProducesResponseType(typeof(clReadNotificaciones), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadNotificaciones>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateNotificaciones objInput)        {            var vUpdated = await _objService.UpdateNotificaciones(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un Notificacione por su ID.        /// </summary>        [HttpDelete("{nNotificacionesID:int}")]        [SwaggerOperation(            Summary = "Eliminar Notificacione",            Description = "Borra un Notificacione si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nNotificacionesID)        {            var success = await _objService.DeleteNotificaciones(nNotificacionesID);            return success ? NoContent() : NotFound();        }    }}